"""Content of GRAVITY_PROVENANCE (Markdown + LaTeX): where every result of sections 11-14 of 7+1.nb comes from, the
decisions taken, the equations used, how everything was checked and with which programs.  Self-contained: every equation
used is written in this document."""
from docgen import Doc
from doc_stage3_common import fmt, mnum


def build(D, today, runs):
    ck = D['checks']['grav']; refd = D['ref'].get('grav', ('', '', {})); ref = refd[2]; nm = D['nums']['grav']
    nck = len(ck); nok = sum(1 for c in ck if c[1] == 'True')
    rb = [(k, v) for k, v in ref.items() if v in ('True', 'False')]
    d = Doc('Gravity on the 7+1 spacetime: provenance',
            'Sources, decisions, derivations and the verification record of the curvature, the Einstein and Lovelock tensors, the '
            'generalized frame matrices, the canonical spin connection, the covariant Dirac equation of dirac16complex and the three '
            'cosmological epochs — sections 11–14 of the notebook 7+1.nb',
            ['Repository: github.com/once-ere/7plus1 — prepared for Nash',
             'Notebook: 7+1.nb (Wolfram Language 15.0.1)', 'Document generated by tools/make_docs.py on ' + today],
            'This record states what was asked, what was used, every decision taken with the equation behind it, how each result '
            'was derived and how it was checked: the %d checks of sections 11–14 of 7+1.nb (%d True), the %d boolean checks of the '
            'independent Python program tools/ref_gravity.py (%d True), the comparison of the printed numbers, the program versions '
            'and the SHA-256 hashes of the files.' % (nck, nok, len(rb), sum(1 for k, v in rb if v == 'True')))

    # ------------------------------------------------------------------------------------------------
    d.h1('1. The task')
    d.p('This stage of the project asked for the following (summarized; the original wording is the author’s private working material '
        'and is not reproduced):')
    d.ol(['Take the IDEAS of the repository github.com/once-ere/Dirac_claude, which is cast on a 4+4 spacetime with four time-like '
          'coordinates and a definite warped metric, and rebuild them on the 7+1 spacetime of this project: ONE time-like coordinate '
          '$x_0$ and SEVEN space-like coordinates $x_1,\\dots,x_7$. The 4+4 metric of Dirac_claude is not used.',
          'Einstein and Lovelock tensors of 7+1 spacetime.',
          'Generalized frame matrices, a non-trivial canonical spin connection that couples gravity to dirac16complex, and a total '
          'covariant derivative under which the frame matrices are constant.',
          'Kohn–Sham theory of dirac16complex in gravitational fields (primordial near $x_0=0$, modern, far future), its self-coupling, '
          'and the totality of the Standard Model (sections 15–19 of 7+1.nb; this record covers sections 11–14).',
          'Compute the Lovelock tensors as in the author’s reference notebook Einstein-Lovelock-7+1-Nash.nb and do NOT use its section '
          '"FAILED Model metric g71; DO NOT USE!".',
          'For every documentation file a companion provenance file and a symbol file, each in Markdown and LaTeX, the LaTeX compiled to '
          'PDF; no document refers the reader to another one, and every equation used is written in the document that uses it.',
          'Push every completed stage to github.com/once-ere/7plus1, respecting the repository’s .gitignore; use only the Wolfram front '
          'end WolframNB.exe of Wolfram 15.0.1.'])
    d.p('The coordinates of 7+1.nb are kept: $X=(x_0,\\dots,x_7)$, $x_0$ the time (the direction of the octonion unit), $x_1,x_2,x_3$ '
        'ordinary space, $x_4,\\dots,x_7$ auxiliary space; metric signature $(+,-,\\dots,-)$ with $\\eta=\\mathrm{diag}(+1,-1,\\dots,-1)$.')

    # ------------------------------------------------------------------------------------------------
    d.h1('2. Inputs')
    d.h2('2.1 Objects of the earlier sections of 7+1.nb')
    d.p('Sections 11–14 use, unchanged, the coordinates `X = {x0, …, x7}`, the metric `η17` $=\\eta$, the identity and zero matrices '
        '`ID16`, `Zero16`, the check registry `check[name, test]`, and the real 16×16 Dirac matrices `Γ17[A]` of section 4 with')
    d.eq(r'\Gamma_0=\begin{pmatrix}0&1_8\\1_8&0\end{pmatrix},\qquad \Gamma_i=\begin{pmatrix}\tau^O_i&0\\0&-\tau^O_i\end{pmatrix}\ (i=1,\dots,7),'
         r'\qquad \Gamma_A\Gamma_B+\Gamma_B\Gamma_A=2\eta_{AB}1_{16},\qquad \Gamma^A=\eta^{AA}\Gamma_A,')
    d.p('where the real 8×8 matrices $\\tau^O_i$ represent the seven imaginary octonion units ($(\\tau^O_i)^2=-1_8$, '
        '$\\tau^O_i\\tau^O_j+\\tau^O_j\\tau^O_i=-2\\delta_{ij}1_8$), and the Hamiltonian matrices `αD[j]` $=\\Gamma^0\\Gamma^j$, `βD` $=\\Gamma_0$ of '
        'section 7. Before sections 11 and following were appended, the evaluated notebook was copied to '
        '`backups/7+1_2026-10-26_before_gravity.nb` (excluded from the repository by .gitignore).')
    if D.get('backup'):
        d.code('backups/7+1_2026-10-26_before_gravity.nb\n%d bytes\nSHA-256 %s' % (D['backup'][1], D['backup'][0]), 'text')
    d.h2('2.2 The reference notebook Einstein-Lovelock-7+1-Nash.nb')
    d.p('The author’s notebook Einstein-Lovelock-7+1-Nash.nb (P. L. Nash, 2022, GNU GPL; corrected version of 27 October 2026, with its '
        'PDF printout) shows how the Lovelock tensors are to be computed. It is the author’s file and is not part of the repository. '
        'Taken from it, unchanged in substance:')
    d.ul(['the xAct packages xCoba and xTras, the manifold `M8` with the abstract indices $a$, $b$, $c$, $d$, $f$, $i$, $j$, $k$, $l$, $m$, $n$, $p$, $q$, $r$, $s$, $y$, the '
          'chart `chartM8` with coordinate scalars `x0[]`, …, `x7[]`, and `MyArrayComponents`;',
          'the generalized Kronecker delta `kδ[lower_, upper_] := Det[Outer[delta, lower, upper]]`;',
          'the three Lovelock tensors with their normalization,',
          ])
    d.eq(r'\mathrm{Lovelock}_k=-\frac{1}{2^{k+1}}\,R_{c_1d_1}{}^{f_1i_1}\cdots R_{c_kd_k}{}^{f_ki_k}\;\delta^{b\,c_1d_1\cdots c_kd_k}_{a\,f_1i_1\cdots f_ki_k}\quad(k=1,2,3),'
         r'\qquad \mathrm{Lovelock}_1=R_a{}^b-\tfrac12\delta_a{}^bR,')
    d.ul(['the evaluation of components by assigning a component metric and setting `CD = LC[g]`, `RiemannCD = Riemann[CD]`, '
          '`RicciCD = Ricci[CD]`, `RicciScalarCD = RicciScalar[CD]`, `EinsteinCD = Einstein[CD]`;',
          'the form of the vacuum field equations and the procedure of solving them for $w_2,w_3$ (and $\\Lambda$):'])
    d.eq(r'0=-\Lambda\,\delta^\mu_\nu+H^{-2}w_1\,\mathrm{Lovelock}_1+H^{-4}w_2\,\mathrm{Lovelock}_2+H^{-6}w_3\,\mathrm{Lovelock}_3,')
    d.p('with the justification it quotes from D. Lovelock and H. Rund, *Tensors, Differential Forms, and Variational Principles* (Dover), '
        'Remark 2 after Eq. (4.38): in $n$ dimensions the most general symmetric divergence-free tensor built from the metric and its '
        'first two derivatives is')
    d.eq(r'A^{lh}=\sqrt{|g|}\sum_{k=1}^{m-1}\alpha_{(k)}\,g^{jl}\,\delta^{h h_1\cdots h_{2k}}_{j j_1\cdots j_{2k}}\,'
         r'R^{j_1j_2}{}_{h_1h_2}\cdots R^{j_{2k-1}j_{2k}}{}_{h_{2k-1}h_{2k}}+\lambda\sqrt{|g|}\,g^{lh},\qquad m-1=\frac82-1=3\ \ (n=8).')
    d.p('NOT taken: the section "FAILED Model metric g71; DO NOT USE!" of the reference notebook (its model metric and the solution '
        'found for it); its author states that it never worked for the 7+1 signature. No metric of that section appears in this '
        'project. Changed: the signature declaration `DefMetric[{7, 1, 0}, …]` (the mostly-plus convention) became `DefMetric[{1, 7, 0}, …]` '
        'to match $\\eta=\\mathrm{diag}(+1,-1,\\dots,-1)$ of this notebook (the declaration does not enter the Lovelock tensors with mixed '
        'indices, and both declarations give the same sign of the determinant, $(-1)^q=-1$ for $q=7$ and for $q=1$, as a separate kernel with xTensor 1.2.0 '
        'confirmed: `SignDetOfMetric` is $-1$ for a metric declared `{1, 7, 0}` and for one declared `{7, 1, 0}`); the metric symbol is called `g71` as in the reference notebook.')
    if D.get('sha_reference'):
        d.code('Einstein-Lovelock-7+1-Nash.nb   SHA-256 %s\nEinstein-Lovelock-7+1-Nash.pdf  SHA-256 %s' % D['sha_reference'], 'text')
    d.h2('2.3 Software and other sources')
    vv = D.get('versions', {})
    d.ul(['Wolfram Language 15.0.1 (the front end WolframNB.exe in `C:\\Program Files\\Wolfram Research\\Wolfram\\15.0.1`).',
          'xAct (J. M. Martín-García, D. Yllanes, T. Nutma and others; GPL; www.xact.es), versions as printed by section 12.2 of 7+1.nb: %s.'
          % (D.get('xact_versions') or '?'),
          'Python %s with sympy %s, numpy %s, scipy %s, mpmath %s (the independent programs).' % (
              vv.get('python', '?'), vv.get('sympy', '?'), vv.get('numpy', '?'), vv.get('scipy', '?'), vv.get('mpmath', '?')),
          'Ideas (no formulas or metrics) from the repository github.com/once-ere/Dirac_claude: a 16-component field coupled to gravity '
          'by the canonical spin connection, Einstein–Lovelock gravity, a primordial pair-creation epoch, a Kohn–Sham treatment, the '
          'Standard Model on a lower-dimensional world surface.',
          'The author’s private notes on vielbeins in $n$ dimensions (Cartan’s structure equation, a static metric with a radial '
          'coordinate, the Dirac equation, the Noether current and the U(1) coupling): their 7+1 versions were derived and checked anew '
          '(section 4 below gives the derivations, section 5 the checks). The notes are private and not part of the repository.',
          'Standard textbook results, each derived and checked here: the Landau–Lifshitz curvature conventions, the Lanczos tensor, Kasner '
          'solutions, the Gibbons–Hawking temperature $H/(2\\pi)$, the Landau–Zener formula.'])

    # ------------------------------------------------------------------------------------------------
    d.h1('3. Decisions')
    d.table(['#', 'decision', 'reason / equation'], [
        ['1', 'Christoffel symbols are written $\\{{}^{\\lambda}_{\\mu\\nu}\\}$', '$\\Gamma$ is reserved for the Dirac matrices'],
        ['2', 'Riemann tensor of Landau and Lifshitz: $R^\\rho{}_{\\sigma\\mu\\nu}=\\partial_\\mu\\{{}^\\rho_{\\sigma\\nu}\\}-\\partial_\\nu\\{{}^\\rho_{\\sigma\\mu}\\}+\\{{}^\\rho_{\\mu\\lambda}\\}\\{{}^\\lambda_{\\sigma\\nu}\\}-\\{{}^\\rho_{\\nu\\lambda}\\}\\{{}^\\lambda_{\\sigma\\mu}\\}$, $R_{\\sigma\\nu}=R^\\rho{}_{\\sigma\\rho\\nu}$',
         'with $(+,-,\\dots,-)$: $G^\\mu{}_\\nu-\\bar\\Lambda\\delta^\\mu_\\nu=\\kappa T^\\mu{}_\\nu$ with $T^0{}_0>0$; agrees with xAct (the reference notebook’s '
         '$\\mathrm{Lovelock}_1$ equals this $G$)'],
        ['3', 'Lovelock tensors normalized as in the reference notebook, $E^{(k)}=-2^{-(k+1)}\\delta RR\\cdots$', '$E^{(1)}=G$, $E^{(2)}=$ Lanczos tensor'],
        ['4', 'two forms of the field equations: $w$-form (reference notebook) and $\\alpha$-form', '$\\alpha_2=w_2/(w_1H^2)$, $\\alpha_3=w_3/(w_1H^4)$, $\\bar\\Lambda=\\Lambda H^2/w_1$'],
        ['5', 'xAct signature declaration $\\{1,7,0\\}$', 'one plus sign (time $x_0$), seven minus signs, as $\\eta$'],
        ['6', 'xAct runs in the notebook kernel; the cell is guarded (`If[! MemberQ[$Manifolds, M8], …]`, `Unset` of the component assignments); '
         '`tools/run_eval.wl` evaluates the notebook in a fresh kernel', 'the cell can be evaluated twice while the notebook stays open; xAct keeps its '
         'definitions in the kernel, while a reopened notebook gets a new private context'],
        ['7', '`xActLovelock` returns the Transpose of `MyArrayComponents`', 'the array has the lower index $a$ first; the pp-wave ($E^0{}_1=-E^1{}_0$) fixes the order'],
        ['8', 'a second, independent computation (pair-set sums) is kept', 'exact agreement with xAct is a strong check; it also works on exact rational tables'],
        ['9', 'the inhomogeneous metric is an explicit polynomial, checked exactly at $x_0=1/2$, $x_4=1/3$', 'symbolic checks with arbitrary functions of two variables took hours'],
        ['10', 'exponential expansion is evaluated from the xAct components of the cosmological metric (`xlCos`), not by a new xAct run', 'xAct’s final Simplify with symbolic exponentials is very slow'],
        ['11', 'the spinor connection is built as `Zero16 + Sum[…]`', 'a sum of zeros would otherwise be the scalar 0, not a 16×16 matrix'],
        ['12', 'the 16-component mode equation is reduced with $\\mathcal Z=\\mathcal A\\mathcal B\\beta$, $\\mathcal Z^2=-1$', 'two classes of states ($\\pm m\\sigma_3$), created at different rates'],
        ['13', 'pair creation is integrated from $10^{-15}\\lambda$ to $300\\lambda$ (Kasner), from $-\\ln2000$ to $\\ln(10^6/M^2)$ (de Sitter)', 'adiabatic before and after; checked by $|\\alpha|^2+|\\beta|^2=1$ and the Landau–Zener formula'],
    ], widths=[0.055, 0.495, 0.45], small=True)

    # ------------------------------------------------------------------------------------------------
    d.h1('4. Derivations')
    d.p('**Sectional curvatures of the cosmological metric.** In the frame $e=\\mathrm{diag}(1,a,a,a,b,b,b,b)$ every $R^{AB}{}_{CD}$ is '
        'diagonal on index pairs, with')
    d.eq(r"K_{0i}=-(H_a'+H_a^2),\quad K_{0k}=-(H_b'+H_b^2),\quad K_{ij}=-H_a^2,\quad K_{kl}=-H_b^2,\quad K_{ik}=-H_aH_b,")
    d.p('In $L_k=2^{-k}\\delta^{\\alpha_1\\beta_1\\cdots}_{\\gamma_1\\delta_1\\cdots}R^{\\gamma_1\\delta_1}{}_{\\alpha_1\\beta_1}\\cdots$ every ordered '
        'sequence of $2k$ different indices contributes $2^k\\prod_iK_{\\alpha_i\\beta_i}$ (each lower pair is the upper pair in one of its two '
        'orders), so $L_k$ is a sum over SETS of $k$ disjoint index pairs, and $E^{(k)\\mu}{}_\\mu$ (no sum) is $-\\tfrac12$ times the same sum '
        'over the pairs that avoid $\\mu$:')
    d.eq(r'L_k=2^kk!\sum_{\{p_1,\dots,p_k\}}K_{p_1}\cdots K_{p_k},\qquad E^{(k)\mu}{}_\mu=-2^{k-1}k!\sum_{\{p_1,\dots,p_k\}\not\ni\mu}K_{p_1}\cdots K_{p_k}.')
    d.p('Counting the pairs among $x_1,\\dots,x_7$ (3 inside ordinary space, 6 inside the auxiliary space, 12 mixed) and the sets of two '
        'disjoint pairs (18 of type ordinary–auxiliary, 12 ordinary–mixed, 3 auxiliary–auxiliary, 36 auxiliary–mixed, 36 mixed–mixed) gives')
    d.eq(r'G^0{}_0=-\big(3K_{12}+6K_{45}+12K_{14}\big)=3H_a^2+12H_aH_b+6H_b^2,\\ '
         r'E^{(2)0}{}_0=-4\big(12H_a^3H_b+54H_a^2H_b^2+36H_aH_b^3+3H_b^4\big)=-12H_b\big(4H_a^3+18H_a^2H_b+12H_aH_b^2+H_b^3\big).')
    d.p('**Kasner exponents.** With $a=x_0^p$, $b=x_0^q$: $H_a=p/x_0$, $H_a\'=-p/x_0^2$ (likewise for $b$), and $x_0^{2k}E^{(k)}$ is a '
        'polynomial in $p,q$. Einstein: $3p+4q=1$, $3p^2+4q^2=1$. Gauss–Bonnet: $3p+4q=3$ and $-203p^3+81p^2+351p+27=0$. Cubic: $3p+4q=5$ and '
        '$(p,q)=(-15/7,20/7)$, besides the degenerate families $q=0$ and $p=0$.')
    d.p('**Spin connection of the cosmological metric.** From $\\omega_\\mu{}^A{}_B=e^A{}_\\nu(\\partial_\\mu e_B{}^\\nu+\\{{}^\\nu_{\\mu\\lambda}\\}e_B{}^\\lambda)$ with '
        '$\\{{}^0_{ii}\\}=aa\'$, $\\{{}^i_{0i}\\}=a\'/a$: $\\omega_i{}^0{}_i=a\'$, hence $\\Omega_i=\\tfrac14(\\omega_{i0i}\\Gamma^0\\Gamma^i+\\omega_{ii0}\\Gamma^i\\Gamma^0)=\\tfrac{a\'}{2}\\Gamma_i\\Gamma_0$.')
    d.p('**Static radial metric (Cartan).** $e^0=\\sqrt f dx_0$, $e^1=\\sqrt h dr$, $e^k=r dx^k$; $de^0=\\frac{f\'}{2\\sqrt f}dr\\wedge dx_0$, '
        '$de^k=dr\\wedge dx^k$, $de^1=0$; Cartan’s equation $de^A+\\omega^A{}_B\\wedge e^B=0$ gives')
    d.eq(r"\omega^0{}_1=\frac{f'}{2\sqrt{fh}}\,dx_0,\quad \omega^k{}_1=\frac{dx^k}{\sqrt h},\quad \Omega_0=\frac{f'}{4\sqrt f\sqrt h}\Gamma_1\Gamma_0,\quad \Omega_k=\frac{1}{2\sqrt h}\Gamma_1\Gamma_k,\quad "
         r"\Gamma^\mu\Omega_\mu=\frac{1}{\sqrt h}\Big(\frac{f'}{4f}+\frac3r\Big)\Gamma^1 .")
    d.p('**Exponential vacuum solutions.** For $a=e^{Hx_0}$, $b=e^{q_HHx_0}$ the vacuum equations are linear in $(w_2,w_3,\\Lambda)$, and the '
        'divergence identity $\\frac{d}{dx_0}E^{(k)0}{}_0+3H_a(E^{(k)0}{}_0-E^{(k)1}{}_1)+4H_b(E^{(k)0}{}_0-E^{(k)4}{}_4)=0$ with constant entries makes '
        'them of rank 2. For $q_H=-1$: $w_2=\\Lambda/4-w_1/2$, $w_3=w_1/24-\\Lambda/36$.')
    d.p('**de Sitter pair creation.** For $i\\dot c=(ke^{-Hx_0}\\sigma_1+M\\sigma_3)c$ the change of variable $z\\propto e^{-Hx_0}$ gives Whittaker '
        'functions; their connection formula yields $|\\beta|^2=1/(e^{2\\pi M/H}+1)$, checked numerically below.')

    # ------------------------------------------------------------------------------------------------
    d.h1('5. Verification')
    lg = D.get('log', {})
    d.p('**Evaluation of 7+1.nb.** The notebook was generated by `tools/make_7p1_nb.py` (which executes `tools/nb_part_gravity.py`, '
        '`tools/nb_part_ks_gravity.py`, `tools/nb_part_sm.py`) and evaluated by `tools/run_eval.wl` in a fresh kernel of Wolfram %s; seconds %s, message '
        'cells %s, finished %s. The final section of the notebook lists %s checks; all passed: %s.' % (
            lg.get('version', '15.0.1'), lg.get('seconds', '?'), lg.get('message cells', '?'), lg.get('finished', '?'),
            D.get('n_checks_total') if D.get('n_checks_total') is not None else '?', D.get('all_passed', '?')))
    d.p('**The checks of sections 11–14 of 7+1.nb:**')
    d.table(['#', 'check', 'result', 'section'],
            [[str(i + 1), '`' + c[0].replace('`', "'") + '`', c[1], (c[3][:4] if c[3] else c[2][:3])] for i, c in enumerate(ck)],
            widths=[0.055, 0.745, 0.08, 0.12], small=True)
    d.p('**The independent Python program** tools/ref_gravity.py (its own curvature and Lovelock engine tools/lovelock71.py; the '
        'Dirac matrices rebuilt from the split octonions of 4+4.nb by tools/ref71.py). Its boolean checks:')
    d.table(['#', 'check', 'result'], [[str(i + 1), '`' + k.replace('`', "'") + '`', v] for i, (k, v) in enumerate(rb)],
            widths=[0.055, 0.825, 0.12], small=True)
    d.p('**Numbers computed by both programs:**')
    rows = []
    def pyl(key):
        import re
        v = ref.get(key, '')
        return [float(x) for x in re.findall(r'-?\d+\.\d+(?:e-?\d+)?', v)]
    kb = [mnum(nm.get('Kasner beta2 (1,1)', '') or ''), mnum(nm.get('Kasner beta2 (2,1)', '') or ''), mnum(nm.get('Kasner beta2 (1,3)', '') or '')]
    pk = pyl('Kasner (Einstein branch), massless: |beta|^2 for (|p|, |q|) = (1,1), (2,1), (1,3)')
    for i, lab in enumerate(['(1,1)', '(2,1)', '(1,3)']):
        rows.append(['Kasner $|\\beta|^2$ at $(|\\vec p|,|\\vec q|)=%s$' % lab, fmt(kb[i], 8), fmt(pk[i] if len(pk) > i else None, 8)])
    for lab, key in (('$M/H=0.25$', 'dS beta2 M/H=0.25'), ('$M/H=0.5$', 'dS beta2 M/H=0.5'), ('$M/H=1$', 'dS beta2 M/H=1')):
        rows.append(['de Sitter $|\\beta|^2$, ' + lab, fmt(mnum(nm.get(key, '') or ''), 9), '—'])
    d.table(['quantity', '7+1.nb', 'Python'], rows, widths=[0.5, 0.25, 0.25])
    d.p('**SHA-256 of the files** (at the time this document was generated):')
    d.code('\n'.join('%-34s %s' % (f, h) for f, h in D.get('sha', {}).items()), 'text')
    for title, out, *rest in (runs or []):
        if 'ref_gravity' in title:
            d.p('**Output of %s** (complete):' % title)
            d.code(out, 'text')
    return d
